def count_random_pictures(n, m):
    # A row of length m can have a random pattern in 2^m ways
    # We only need to consider both the first and second row together for larger n
    if n == 1:
        # Only one row, count the random patterns directly
        return pow(2, m, MOD)
    elif n == 2:
        # If there are only two rows, we need to consider only the pattern where no two adjacent cells in the same row or column are the same
        # We will use dynamic programming approach
        dp = [[0] * (1 << m) for _ in range(2)]
        # Initialize for the first row
        for mask in range(1 << m):
            if is_valid(mask, m):
                dp[0][mask] = 1

        for i in range(1, n):
            for prev_mask in range(1 << m):
                if dp[i-1][prev_mask] == 0:
                    continue
                for mask in range(1 << m):
                    if is_valid(mask, m) and is_compatible(prev_mask, mask, m):
                        dp[i % 2][mask] = (dp[i % 2][mask] + dp[(i-1) % 2][prev_mask]) % MOD

        # Sum up all possibilities for the last row
        return sum(dp[(n-1) % 2]) % MOD

    else:
        # For more than 2 rows, use the fact that the problem becomes equivalent to having only 2 rows
        return pow(2, m, MOD)

def is_valid(mask, m):
    # Check if the mask is a valid pattern for a single row
    for i in range(m - 1):
        if (mask & (1 << i)) and (mask & (1 << (i + 1))):
            return False
    return True

def is_compatible(prev_mask, curr_mask, m):
    # Check if the current row is compatible with the previous row
    for i in range(m):
        if (prev_mask & (1 << i)) and (curr_mask & (1 << i)):
            return False
    return True

